for idx,(name,pcm,rel,vol,loopflag,ll) in enumerate(insts, start=1):
    calls.append({"name":"instrument_set","arguments":{"instrument":idx,"name":name}})
    calls.append({"name":"sample_create_from_pcm","arguments":{"instrument":idx,"sample":0,"encoding":"int16","name":name,"pcm":b64_int16(pcm)}})
    args={"instrument":idx,"sample":0,"name":name,"volume":vol,"panning":128,"relative_note":rel}
    if loopflag:
        args.update({"loop_start":0,"loop_length":len(pcm),"flags":1})
    calls.append({"name":"sample_set","arguments":args})

for p in range(8):
    calls.append({"name":"pattern_set_length","arguments":{"pattern":p,"rows":64}})
    calls.append({"name":"pattern_clear","arguments":{"pattern":p}})
for pos,pat in enumerate([0,1,2,3,4,5,6,7]):
    calls.append({"name":"order_set","arguments":{"position":pos,"pattern":pat}})

note_names=['C-','C#','D-','D#','E-','F-','F#','G-','G#','A-','A#','B-']
def note(n):
    # midi-ish C-4=48? Produce FT2 strings by octave n//12
    return f"{note_names[n%12]}{n//12}"
def add(p,row,ch,n=None,ins=None,vol=None,eff=None,param=None):
    d={"pattern":p,"row":row,"channel":ch}
    if n is not None: d['note']=note(n) if isinstance(n,int) else n
    if ins is not None: d['instrument']=ins
    if vol is not None: d['volume']=vol
    if eff is not None: d['effect']=eff; d['effect_param']=param or 0
    calls.append({"name":"pattern_set_cell","arguments":d})

# Musical data in C# minor: C# D# E F# G# A B (C# octave n: C#4=49)
bass_prog=[37,44,42,40]  # C#2, G#2, F#2, E2 approximated by octave scheme
chords=[[49,52,56],[44,49,52],[42,45,49],[40,44,47]]
leadA=[56,56,59,61,64,61,59,56, 54,56,59,61,64,66,64,61]
leadB=[68,66,64,61, 64,61,59,56, 59,61,64,68, 66,64,61,59]
# Need C# minor actual n: C#4=49 E=52 G#=56 B=59 etc.
leadA=[56,59,61,64, 61,59,56,52, 54,56,59,61, 64,66,64,61]
leadB=[68,66,64,61, 64,61,59,56, 59,61,64,68, 66,64,61,59]

def drums(p, full=True):
    for r in range(0,64,16):
        add(p,r,3,37,5,60); add(p,r+8,3,37,5,54)
        add(p,r+4,4,49,6,48); add(p,r+12,4,49,6,50)
    for r in range(0,64,4): add(p,r,5,61,7,22 if r%8 else 28)
    if full:
        for r in range(14,64,16): add(p,r,5,61,8,30)

def bassline(p, variant=0):
    for bar,root in enumerate(bass_prog):
        base=bar*16
        seq=[root,root+12,root+7,root+12, root,root+10,root+7,root+12]
        if variant: seq=[root,root+12,root+7,root+15, root+12,root+10,root+7,root+5]
        for i,n in enumerate(seq): add(p,base+i*2,2,n,3,44 if i%2==0 else 36)

def arps(p, bright=False):
    for bar,chd in enumerate(chords):
        base=bar*16
        seq=(chd+[chd[0]+12,chd[1]+12,chd[2]+12])
        for i in range(16):
            n=seq[(i*2+(1 if bright else 0))%len(seq)]
            add(p,base+i*4%16,6,n+12,4,22 if not bright else 28)

def chordstabs(p):
    for bar,chd in enumerate(chords):
        for off in [0,8]:
            for j,n in enumerate(chd): add(p,bar*16+off,j%2+7,n+12,10,20)

def lead(p, mel, ch=0, ins=1, start=0, echo=True):
    for i,n in enumerate(mel):
        r=start+i*4
        add(p,r,ch,n,ins,46)
        if echo and r+2<64: add(p,r+2,9,n,2,18)

# pattern 0 intro sparse
for bar,root in enumerate(bass_prog):
    add(0,bar*16,2,root,3,38)
    for i,n in enumerate(chords[bar]): add(0,bar*16+i*2,6,n+12,4,20)
for r in range(0,64,8): add(0,r,5,61,7,18)
add(0,48,8,49,9,32)

# main patterns
for p in [1,2,3,4,5,7]:
    drums(p, True); bassline(p, p in [2,5,7]); arps(p, p in [3,5,7]); chordstabs(p)
lead(1,leadA); lead(2,leadA[:8]+[66,68,66,64,61,64,61,59])
lead(3,leadB,0,1); lead(4,[61,64,68,73, 71,68,66,64, 61,64,66,68, 73,76,73,71],0,1)
lead(5,leadA,0,1); lead(7,leadB[:8]+leadA[8:],0,1)
# countermelodies/harmony
for p in [2,3,5,7]:
    for i,n in enumerate([49,52,54,56, 59,56,54,52]*2): add(p,i*4+1,1,n+12,2,26)
# breakdown pattern 6
for bar,root in enumerate(bass_prog):
    add(6,bar*16,2,root,3,32)
    for i,n in enumerate(chords[bar]*2): add(6,bar*16+i*3%16,6,n+24,4,20)
for r in range(0,64,8): add(6,r,5,61,7,16)
lead(6,[56,0,59,0,61,0,64,0, 68,0,66,0,64,0,61,0],0,1,0,False)
# remove invalid zeros? Actually note 0 C-0 maybe ok used rests not desired, it will bass. Replace silence by skip? too late; cell note C-0 creates blips. Let's clear by simply not generating? Above uses 0. We'll clear those cells.
for i,n in enumerate([56,None,59,None,61,None,64,None,68,None,66,None,64,None,61,None]):
    r=i*4
    if n is not None: add(6,r,0,n,1,40)
add(6,60,8,49,9,38)

# Add pattern break? avoid. Ensure final pattern has pickups resolving to pattern 1
add(7,60,0,64,1,48); add(7,62,0,61,1,42)

with open('/workspace/batch.json','w') as f: json.dump(calls,f)
print(len(calls),'calls')
